+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.sidenav.SideNav;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.jooq.impl.DSL.name;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationShowsNamesAndAlphabeticallyOrderedSpecialtiesWithoutAuthentication() {
+        navigate(WelcomeView.class);
+        SideNav menu = assertDoesNotThrow(() -> find(SideNav.class).single(), "Expected main navigation");
+        test(menu).clickItem("Veterinarians");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        var grid = test(vetsGrid());
+        assertEquals(List.of("First Name", "Last Name", "Specialties"),
+                List.of(grid.getHeaderCell(0), grid.getHeaderCell(1), grid.getHeaderCell(2)));
+        assertEquals(6, grid.size());
+        assertEquals("James", grid.getCellText(0, 0));
+        assertEquals("Carter", grid.getCellText(0, 1));
+        assertEquals("none", grid.getCellText(0, 2));
+        assertEquals("Linda", grid.getCellText(1, 0));
+        assertEquals("Douglas", grid.getCellText(1, 1));
+        assertEquals("dentistry, surgery", grid.getCellText(1, 2));
+        assertEquals("radiology", grid.getCellText(3, 2));
+        assertEquals("surgery", grid.getCellText(4, 2));
+        assertEquals("radiology", grid.getCellText(5, 2));
+        assertEquals(6, dsl.fetchCount(VETS), "Browsing must not change the directory");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void lazyProviderReturnsBoundedPagesWithoutDuplicatesOrMissingVets() {
+        // Identical names exercise the ID tie-breaker across page boundaries.
+        var insert = dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME);
+        for (int i = 0; i < 120; i++) {
+            insert.values("Alex", "Taylor");
+        }
+        insert.execute();
+        navigate(VetsView.class);
+        var provider = vetsGrid().getDataProvider();
+        assertFalse(provider.isInMemory());
+        assertEquals(126, provider.size(new Query<>()));
+
+        List<Integer> loadedIds = new ArrayList<>();
+        int chunkSize = 17;
+        for (int offset = 0; offset < 126; offset += chunkSize) {
+            var page = provider.fetch(new Query<>(offset, chunkSize, List.of(), null, null)).toList();
+            assertEquals(Math.min(chunkSize, 126 - offset), page.size());
+            loadedIds.addAll(page.stream().map(Vet::id).toList());
+        }
+        assertEquals(dsl.select(VETS.ID).from(VETS)
+                .orderBy(VETS.LAST_NAME, VETS.FIRST_NAME, VETS.ID).fetch(VETS.ID), loadedIds);
+        assertTrue(provider.fetch(new Query<>(126, chunkSize, List.of(), null, null)).findAny().isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryShowsGridWithNoRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, test(vetsGrid()).size());
+        assertTrue(vetsGrid().getDataProvider().fetch(new Query<>()).findAny().isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsApplicationErrorAndRemovesGrid() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = vetsGrid();
+        // DDL is rolled back with the test; the next callback sees a real database error.
+        dsl.alterTable(VETS).renameTo(name("unavailable_vets")).execute();
+
+        grid.getDataProvider().size(new Query<>());
+
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void laterPageFailureShowsApplicationErrorAndRemovesPreviouslyLoadedVets() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = vetsGrid();
+        assertFalse(grid.getDataProvider().fetch(new Query<>(0, 2, List.of(), null, null)).toList().isEmpty());
+        dsl.alterTable(VET_SPECIALTIES).renameTo(name("unavailable_vet_specialties")).execute();
+
+        grid.getDataProvider().fetch(new Query<>(2, 2, List.of(), null, null)).toList();
+
+        assertErrorView();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> vetsGrid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected veterinarians grid");
+    }
+
+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(), "Expected application error view");
+        assertFalse(assertDoesNotThrow(() -> find(Paragraph.class).single(), "Expected error message")
+                .getText().isBlank());
+        assertTrue(find(Grid.class).all().isEmpty(), "No vet list should remain after a data-access failure");
+    }
+}
